"use strict";
window.ROBO_MISION_GUIAS_V28={"01-01":{"prep":"Solo micro:bit; dibuja en papel dos caras distintas antes de abrir MakeCode.","program":["En «para siempre», inserta «mostrar leds» y dibuja la primera cara","añade «pausa (ms)» con 400","coloca el segundo dibujo y otra pausa de 400 ms."],"test":"Al descargar, alterna cara A y cara B sin tocar botones durante 10 s.","levels":[{"task":"Usa dos dibujos y dos pausas de 400 ms","success":"Se distinguen al menos cinco alternancias"},{"task":"Cambia solo las pausas a 200 y 800 ms y compara","success":"Explica cuál permanece más tiempo"},{"task":"Crea cuatro fotogramas distintos de una emoción","success":"Los cuatro se reconocen en orden y el ciclo se repite"}],"warning":"Un dibujo fuera de «para siempre» solo se ejecuta una vez."},"01-02":{"prep":"Solo micro:bit. Prepara un registro con columnas: pulsación, valor esperado y valor mostrado.","program":["Crea variable «puntos» e inicialízala a 0 dentro de «al iniciar»","al pulsar A cambia «puntos» en +1","al pulsar B cambia en −1 y muestra la variable tras cada cambio."],"test":"Desde 0, pulsa A tres veces y B una: la pantalla debe mostrar 2.","levels":[{"task":"Consigue el recorrido 0→1→2→3→2","success":"Los cuatro valores son correctos"},{"task":"Impide que el marcador baje de 0 usando «si»","success":"Cinco pulsaciones B desde 0 mantienen 0"},{"task":"Añade una condición de victoria al llegar a 10","success":"Aparece un icono una sola vez al alcanzar 10"}],"warning":"No basta con modificar la variable: también debes mostrar su valor."},"01-03":{"prep":"Solo micro:bit. Dibuja en papel seis caras de dado y anota qué valor representa cada una.","program":["Usa «al agitar» como evento de entrada","crea el número aleatorio entre 1 y 6","muestra el resultado con «mostrar número»."],"test":"Agita 12 veces; cada resultado debe estar entre 1 y 6, inclusive.","levels":[{"task":"Haz un dado con números del 1 al 6","success":"Ninguna de 12 tiradas sale fuera del intervalo"},{"task":"Muestra el dado mediante los puntos LED habituales","success":"Las seis caras son distinguibles"},{"task":"Registra 30 tiradas y dibuja frecuencias","success":"La tabla suma 30 y contiene seis categorías"}],"warning":"No uses «elegir al azar 0 a 6»: obtendrías siete resultados posibles."},"01-04":{"prep":"Solo micro:bit. Aleja la placa de imanes, altavoces y motores al calibrar.","program":["Al iniciar ejecuta la calibración de brújula si es necesaria","dentro de «para siempre», lee el rumbo en grados","compara con sectores y muestra N, E, S u O."],"test":"Gira la micro:bit lentamente hacia los cuatro puntos cardinales y apunta la letra mostrada.","levels":[{"task":"Indica N cuando el rumbo esté entre 315° y 45°","success":"Acertará en tres pruebas al norte"},{"task":"Completa los cuatro sectores usando umbrales","success":"Aparecen N, E, S y O en su orientación"},{"task":"Añade ocho rumbos con NE, SE, SO y NO","success":"Ocho sectores aparecen sin huecos ni solapamientos"}],"warning":"El sector norte cruza 0°: necesita condición OR; evita objetos metálicos."},"01-05":{"prep":"Solo micro:bit con acelerómetro integrado; colócala sobre un soporte blando para no dañarla.","program":["Crea evento «al agitar» o compara aceleración con un umbral","muestra señal de alarma","añade una pausa breve para evitar muchas señales por un solo golpe."],"test":"Realiza cinco movimientos suaves y cinco bruscos; registra detecciones.","levels":[{"task":"Muestra alerta al agitar","success":"Al menos cuatro de cinco movimientos bruscos dan aviso"},{"task":"Ajusta umbral para ignorar movimientos suaves","success":"Como máximo una falsa alerta en cinco movimientos suaves"},{"task":"Cuenta los avisos y permite reinicio con botón B","success":"B pone el contador a cero y se visualiza"}],"warning":"No golpees la placa ni la lances: el sensor puede probarse con sacudidas suaves."},"01-06":{"prep":"Solo micro:bit. Usa una hoja con tres columnas: ensayo, tiempo y observación.","program":["Espera un tiempo aleatorio antes de mostrar el icono de salida","guarda «inicio» con «tiempo de ejecución (ms)»","al pulsar A calcula tiempo transcurrido y lo muestra."],"test":"Realiza cinco pruebas; no cuentes pulsaciones anteriores a la señal.","levels":[{"task":"Mide desde icono hasta botón A","success":"Devuelve un tiempo positivo de reacción"},{"task":"Rechaza pulsaciones antes del icono","success":"Una pulsación anticipada no da tiempo válido"},{"task":"Calcula la mejor de cinco marcas","success":"Muestra el menor tiempo válido y la tabla coincide"}],"warning":"Guarda el instante después de mostrar la señal; de lo contrario medirás la espera."},"01-07":{"prep":"Solo micro:bit; los equipos dibujan en papel qué icono corresponde a piedra, papel y tijera.","program":["Al pulsar A genera un número aleatorio 1–3","usa «si / si no» para mostrar el icono correspondiente","borra el icono antes de la siguiente ronda."],"test":"Juega nueve rondas y verifica que solo aparecen tres opciones.","levels":[{"task":"Muestra los tres gestos posibles","success":"Cada gesto aparece correctamente cuando se fuerza su número"},{"task":"Permite competir con un compañero de manera simultánea","success":"Las reglas de victoria están escritas y se aplican"},{"task":"Añade marcador de victorias con botón B","success":"Después de cinco rondas refleja las victorias reales"}],"warning":"No mezcles los números de los gestos entre dos placas: acordad la correspondencia."},"01-08":{"prep":"Solo micro:bit. Coloca una flecha en el borde superior para identificar la orientación.","program":["Lee aceleración X e Y","usa condiciones para diferenciar inclinación izquierda, derecha, hacia delante y atrás","muestra un icono distinto en cada caso."],"test":"Prueba las cuatro inclinaciones sujetando la placa de forma segura.","levels":[{"task":"Diferencia izquierda de derecha","success":"Responde correctamente en cuatro inclinaciones alternadas"},{"task":"Añade delante y atrás sin confundir los ejes","success":"Cuatro direcciones responden correctamente"},{"task":"Incluye zona neutra y calibración inicial","success":"En posición horizontal no activa avisos"}],"warning":"Comprueba el signo de X e Y en tu placa: depende de la orientación de montaje."},"01-09":{"prep":"Dos micro:bit con radio y un grupo asignado. Acordad una distancia corta de prueba.","program":["En la placa árbitro envía «YA» por radio después de una espera aleatoria","ambas placas muestran la señal","cada jugador pulsa A y registra su tiempo local."],"test":"Haz tres rondas y comprueba que una salida falsa no gana.","levels":[{"task":"Ambos reciben la señal de salida","success":"Las dos placas muestran YA al enviar el mensaje"},{"task":"Cada jugador mide su reacción","success":"Se muestran dos tiempos válidos por ronda"},{"task":"Envía las marcas al árbitro y anuncia ganador","success":"Tres rondas acaban con ganador o empate justificado"}],"warning":"No compares relojes independientes sin sincronización; transmite las duraciones medidas."},"02-01":{"prep":"Actividad desconectada al principio: papel, lápiz y compañero que actuará como «robot».","program":["Escribe una instrucción por línea para preparar un sándwich ficticio","ordena la secuencia","simula su ejecución literal con un compañero sin explicaciones orales."],"test":"El compañero debe completar la tarea siguiendo solo el texto y señalar ambigüedades.","levels":[{"task":"Redacta seis acciones en orden lógico","success":"El compañero no necesita inventar pasos"},{"task":"Corrige tres instrucciones imprecisas","success":"La segunda ejecución no requiere aclaraciones"},{"task":"Dibuja un diagrama con decisión «¿hay pan?»","success":"La ruta sí/no tiene salida coherente"}],"warning":"Una instrucción como «prepara todo» no especifica qué hacer ni en qué orden."},"02-02":{"prep":"Solo micro:bit. Elige una entrada medible, por ejemplo botón A pulsado o nivel de luz.","program":["Dentro de «para siempre», introduce una condición «si … si no»","en verdadero muestra ✓ y en falso muestra X","deja una pausa entre lecturas."],"test":"Provoca las dos situaciones y anota qué icono corresponde a cada una.","levels":[{"task":"Haz que aparezca ✓ cuando se cumpla la condición","success":"Pruebas con condición cierta y falsa son correctas"},{"task":"Cambia el umbral y explica la diferencia","success":"Anota el valor antiguo, nuevo y dos resultados"},{"task":"Usa dos condiciones combinadas con «y» o «o»","success":"Verifica una tabla de cuatro combinaciones"}],"warning":"El bloque «si» sin rama «si no» no define qué ocurre en el caso contrario."},"02-03":{"prep":"Solo micro:bit. Decide si la cuenta atrás será 5, 10 o 20 segundos.","program":["Crea variable «segundos» y asígnale 5","usa «repetir 5 veces» para mostrarla, esperar 1000 ms y disminuirla en uno","muestra un icono al llegar a cero."],"test":"Cronometra el programa: una cuenta de 5 debe durar aproximadamente cinco segundos.","levels":[{"task":"Cuenta de 5 a 1 y termina con ✓","success":"Muestra cinco números y después ✓"},{"task":"Permite iniciar con A y reiniciar con B","success":"B devuelve el contador a 5 sin valores negativos"},{"task":"Haz un temporizador configurable con A/B","success":"Dos duraciones elegidas terminan correctamente"}],"warning":"Si restas antes de mostrar, la cuenta empezará por 4; fija el orden."},"02-04":{"prep":"Solo micro:bit y una hoja de depuración. El docente prepara un programa con cinco fallos controlados.","program":["Ejecuta el programa y escribe qué esperabas","identifica el evento que falla","cambia un bloque cada vez y prueba de nuevo","anota la causa."],"test":"Presenta una tabla con fallo, hipótesis, cambio y resultado en cinco filas.","levels":[{"task":"Detecta dos fallos sin ayuda","success":"Anota sus síntomas y correcciones"},{"task":"Encuentra y corrige los cinco fallos","success":"Cinco pruebas posteriores se completan"},{"task":"Crea un fallo nuevo y diseña una prueba para detectarlo","success":"Un compañero lo detecta sin pistas"}],"warning":"Cambiar cinco bloques a la vez impide identificar cuál resolvió el fallo."},"02-05":{"prep":"Solo micro:bit; escribe en papel una clave de tres pulsaciones, por ejemplo A–B–A.","program":["Guarda una variable «fase» inicial 0","cada botón avanza solo cuando coincide con la clave","si falla reinicia fase","al llegar a 3 muestra ✓."],"test":"Comprueba la secuencia correcta y tres secuencias falsas.","levels":[{"task":"Desbloquea únicamente con A–B–A","success":"Tres claves falsas no funcionan"},{"task":"Añade contador de errores y reinicio","success":"Tres fallos hacen aparecer alerta"},{"task":"Permite cambiar clave mediante otro modo","success":"La clave nueva funciona y la anterior deja de servir"}],"warning":"Reinicia «fase» tras una tecla errónea para no aceptar claves parciales."},"02-06":{"prep":"Solo micro:bit; decide entradas A para sumar y B para restar, con un valor inicial visible.","program":["Inicializa «total» en 0","«al pulsar A» añade 1","«al pulsar B» resta 1","usa «mostrar número» después de cada operación."],"test":"Comprueba 0→1→2→1→0 con las pulsaciones correspondientes.","levels":[{"task":"Suma y resta correctamente","success":"Coinciden cuatro resultados consecutivos"},{"task":"Introduce un segundo operando y multiplicación","success":"Resuelve tres operaciones escritas en papel"},{"task":"Crea un menú de operaciones sin ambigüedad","success":"Cada botón tiene función indicada en pantalla"}],"warning":"No confundas mostrar «total + 1» con almacenar el cambio en «total»."},"02-07":{"prep":"Solo micro:bit; decide un intervalo reducido de 1 a 9 y escribe reglas para los botones.","program":["Guarda un secreto aleatorio al iniciar","permite modificar el intento con A y confirmar con B","compara secreto e intento para mostrar mayor, menor o acierto."],"test":"Prueba valores inferiores, superiores y exactos; cada uno debe responder distinto.","levels":[{"task":"El juego indica alto/bajo/acierto","success":"Tres casos de comparación correctos"},{"task":"Limita los intentos a cinco","success":"Tras cinco fallos muestra fin del juego"},{"task":"Añade puntuación según intentos gastados","success":"El marcador coincide con las partidas registradas"}],"warning":"No muestres el número secreto durante la partida; inicialízalo solo una vez."},"02-08":{"prep":"Solo micro:bit o maqueta de cartón; dibuja tres estados: rojo, ámbar y verde.","program":["Crea variable «estado» con 0,1,2","en «para siempre» usa condiciones separadas para mostrar cada estado","avanza estado tras una pausa y vuelve a 0."],"test":"Registra tres ciclos completos: siempre rojo→ámbar→verde y vuelta.","levels":[{"task":"Muestra las tres fases ordenadas","success":"Tres ciclos sin saltos"},{"task":"Añade botón de peatón que fuerce rojo","success":"El paso está detenido antes de indicar cruce"},{"task":"Añade estado de avería con parpadeo","success":"Tras simular fallo no queda habilitado el paso"}],"warning":"No permitas que dos estados incompatibles enciendan las salidas simultáneamente."},"02-09":{"prep":"Solo micro:bit; parte de un programa con instrucciones repetidas en al menos tres sitios.","program":["Marca qué secuencia se repite","crea función «aviso» que reúna esos bloques","sustituye repeticiones por llamadas","compara antes y después."],"test":"Ambas versiones deben producir la misma salida en tres ensayos.","levels":[{"task":"Reemplaza una repetición por función","success":"La salida no cambia"},{"task":"Reduce al menos seis bloques duplicados","success":"El código es más corto y conserva resultados"},{"task":"Compara legibilidad con otro grupo y documenta mejoras","success":"Explica dos decisiones de diseño verificables"}],"warning":"Menos bloques no siempre es mejor: no elimines comprobaciones de seguridad."},"03-01":{"prep":"Solo micro:bit. Selecciona un lugar luminoso y otro en sombra sin tapar ventilaciones.","program":["Lee «nivel de luz» en «para siempre» y muestra número","registra valores de ambos lugares","fija umbral intermedio y muestra aviso si la lectura es baja."],"test":"Mide cinco veces en luz y cinco en sombra antes de elegir el umbral.","levels":[{"task":"Muestra un aviso en sombra","success":"Acertará en cuatro de cinco muestras"},{"task":"Ajusta el umbral con tus datos medidos","success":"Explicas por qué ese número separa ambos casos"},{"task":"Crea tres niveles de luz con iconos distintos","success":"Acertará en al menos ocho de diez pruebas"}],"warning":"La pantalla LED sirve de sensor aproximado; no es un luxómetro calibrado."},"03-02":{"prep":"Solo micro:bit y termómetro externo de referencia; deja ambos juntos varios minutos.","program":["Lee «temperatura (°C)» de micro:bit","anota cinco lecturas separadas","compáralas con el termómetro y calcula diferencia media."],"test":"Presenta dos columnas con cinco mediciones y su diferencia.","levels":[{"task":"Visualiza temperatura en micro:bit","success":"Cinco lecturas visibles"},{"task":"Calcula diferencia media frente al termómetro","success":"Operación y unidad están correctas"},{"task":"Aplica una corrección aproximada y comprueba nuevos datos","success":"La diferencia media disminuye"}],"warning":"La micro:bit mide temperatura del chip: no es automáticamente la del aire."},"03-03":{"prep":"Solo micro:bit o sensor analógico del TA647 si se dispone de Shield y pin compatible.","program":["Muestra primero el valor bruto del sensor","observa valores en dos situaciones","fija umbral intermedio","usa «si / si no» para convertir medida en aviso."],"test":"Recoge tres lecturas a cada lado del umbral y comprueba la decisión.","levels":[{"task":"Transforma lectura en dos estados","success":"Se distinguen lectura baja y alta"},{"task":"Explica dos cambios de umbral","success":"Dos tablas muestran decisiones diferentes"},{"task":"Crea histéresis con umbrales de entrada/salida","success":"No parpadea cerca del punto de corte"}],"warning":"No elijas un umbral sin medir los valores reales del montaje."},"03-04":{"prep":"Kit TA647: sensor de humedad, micro:bit, Shield y cables Dupont; maceta con tierra seca y otra húmeda.","program":["Inserta micro:bit en Shield apagada","conecta S→P0, V→tensión admitida por el módulo y G→GND","lee analógico P0 y registra dos referencias","decide «seco» según los valores medidos."],"test":"Mide al menos cinco veces en tierra seca y húmeda; anota si la lectura sube o baja con agua.","levels":[{"task":"Distingue tierra seca y húmeda","success":"Acierta cuatro de cinco ensayos"},{"task":"Convierte lectura en porcentaje orientativo usando tus referencias","success":"0 % y 100 % corresponden a las muestras de calibración"},{"task":"Añade aviso de riego con una banda de tolerancia","success":"La salida permanece estable cerca del umbral"}],"warning":"No asumas que mojado significa número mayor; depende del sensor."},"03-05":{"prep":"Micro:bit V2 con micrófono; sin micro:bit V2, usa el sensor de sonido del TA647 con Shield.","program":["Muestra «nivel de sonido» y realiza 10 lecturas en silencio y 10 con palmadas","guarda el máximo","elige umbral que separe ambos grupos."],"test":"La detección funciona sin gritar ni golpear el micrófono.","levels":[{"task":"Detecta palmadas por encima del umbral","success":"Cuatro de cinco palmadas válidas"},{"task":"Muestra valor máximo de 10 muestras","success":"El máximo coincide con la tabla"},{"task":"Cuenta sucesos con un intervalo de bloqueo","success":"Una palmada no se cuenta varias veces"}],"warning":"El nivel sonoro no equivale a decibelios absolutos; evita datos personales o grabaciones."},"03-06":{"prep":"Micro:bit y módulo de presión compatible del TA647; comprueba modelo, voltaje y biblioteca de la pantalla antes de conectar.","program":["Muestra primero temperatura de micro:bit en su matriz","conecta el sensor de presión mediante la interfaz indicada por su fabricante","lee presión solo con biblioteca compatible","si hay LCD/OLED, añade su extensión I²C correcta."],"test":"Obtén una lectura de presión con unidades y una temperatura; no sustituyas presión por un número inventado.","levels":[{"task":"Muestra temperatura sin sensor externo","success":"La matriz enseña una lectura numérica"},{"task":"Lee presión real con módulo y programa compatibles","success":"Se registra un valor con unidad y origen"},{"task":"Presenta ambas magnitudes y compara tres momentos","success":"Tabla con seis mediciones justificadas"}],"warning":"El ejemplo de temperatura NO mide presión: debes comprobar la interfaz concreta de tu módulo."},"03-07":{"prep":"Robot Maqueen Plus V2 con ultrasonidos en su conector, o HC-SR04 con adaptación de ECHO a 3,3 V.","program":["Instala la extensión Maqueen Plus V2 desde «Extensiones» si usas el robot","lee distancia ultrasónica","muestra cm y compara con umbral de 20 cm."],"test":"Coloca cartón a 10, 20 y 40 cm; registra lectura y aviso sin colisionar.","levels":[{"task":"Detiene el robot antes de obstáculo a 20 cm","success":"Tres pruebas sin contacto"},{"task":"Prueba dos distancias de frenado","success":"Tabla compara ambas sin cambiar velocidad"},{"task":"Añade frenado progresivo en dos zonas","success":"Reduce velocidad antes de detenerse"}],"warning":"ECHO del HC-SR04 puede ser de 5 V; no lo conectes directamente a la entrada de 3,3 V."},"03-08":{"prep":"Sensor de color TA647 y Shield; consigue guía de pines y extensión de ese modelo antes de cablear.","program":["Identifica si el módulo entrega canales RGB o una clasificación","realiza tres lecturas por color","establece criterios para rojo, verde y azul y muestra etiqueta."],"test":"Prueba tres objetos de cada color bajo la misma iluminación.","levels":[{"task":"Clasifica dos colores tras calibrar","success":"Acierta cuatro de seis muestras"},{"task":"Distingue rojo, verde y azul","success":"Acierta siete de nueve muestras"},{"task":"Añade condición «color desconocido» y registra errores","success":"No fuerza una clasificación ante lectura ambigua"}],"warning":"El sensor de color no se programa simplemente leyendo luz de la micro:bit."},"03-09":{"prep":"Elige un solo sensor; prepara una tabla con fecha, condición, medida y unidad.","program":["Define pregunta e hipótesis","recoge cinco lecturas por condición","guarda datos en hoja de cálculo","calcula media y compara series."],"test":"Entrega 10 mediciones reproducibles y un gráfico correctamente rotulado.","levels":[{"task":"Realiza dos series de cinco medidas","success":"10 valores con unidades"},{"task":"Elabora gráfico y compara medias","success":"Conclusión apoyada en datos"},{"task":"Repite el experimento en otro día y compara dispersión","success":"Explica cambios y limitaciones"}],"warning":"No confundas una muestra de un segundo con evidencia suficiente de un fenómeno."},"04-01":{"prep":"Solo micro:bit. Escribe un saludo de menos de 10 caracteres y dibuja un icono.","program":["En «al iniciar» coloca «mostrar cadena» con tu texto","a continuación «mostrar icono»","añade una pausa y prueba que se lee completo."],"test":"Al encender, se ve el saludo seguido del dibujo en ese orden.","levels":[{"task":"Muestra nombre del equipo y un corazón","success":"El texto y el icono se distinguen"},{"task":"Crea mensajes diferentes con A y B","success":"Cada botón muestra su mensaje sin confusión"},{"task":"Diseña aviso accesible con icono y texto corto","success":"Dos compañeros interpretan el mensaje correctamente"}],"warning":"Los textos largos desplazan la pantalla lentamente; calcula su duración."},"04-02":{"prep":"Solo micro:bit y tarjeta con el alfabeto Morse. Usa LED o matriz; no hace falta electrónica externa.","program":["Define punto como luz 200 ms y raya 600 ms","separa señales de una letra 200 ms y letras 800 ms","crea la secuencia SOS: ··· −−− ···."],"test":"Un compañero debe reconocer SOS sin conocer el programa.","levels":[{"task":"Transmite SOS respetando duraciones","success":"El observador identifica las tres letras"},{"task":"Transmite iniciales del equipo","success":"El receptor las descifra sin pistas"},{"task":"Crea codificador de cinco letras usando funciones","success":"Funciona con cinco letras distintas"}],"warning":"Si todos los espacios duran lo mismo, el receptor no distingue letras."},"04-03":{"prep":"Micro:bit V2 con altavoz o zumbador del kit conectado mediante interfaz segura; trabaja a volumen moderado.","program":["Al pulsar A reproduce tres notas distintas con «reproducir tono»","introduce pausas entre notas","al pulsar B reproduce otra secuencia."],"test":"Dos melodías son distinguibles y cada una responde al botón previsto.","levels":[{"task":"Crea melodía original de tres notas","success":"Se reproduce siempre igual"},{"task":"Añade un ritmo con silencios","success":"Un compañero reproduce las pausas con palmas"},{"task":"Crea introducción y final de seis notas","success":"Se identifican dos secciones diferenciadas"}],"warning":"En micro:bit V1 se necesita salida de audio externa; no presupongas altavoz."},"04-04":{"prep":"Tres luces LED externas con resistencias y Shield, o representación en matriz LED si no hay material.","program":["Dibuja tabla rojo/ámbar/verde","usa una variable «estado» para activar una sola salida cada vez","añade tiempos definidos y vuelve al estado inicial."],"test":"Observa tres ciclos sin luces contradictorias.","levels":[{"task":"Crea ciclo con tres fases temporizadas","success":"Rojo y verde nunca coinciden"},{"task":"Añade petición peatonal por botón","success":"El vehículo se detiene antes del paso"},{"task":"Incorpora modo fallo con ámbar intermitente","success":"Se mantiene la prioridad de parada segura"}],"warning":"Verifica resistencias y polaridad de cada LED; la matriz micro:bit es alternativa simulada."},"04-05":{"prep":"LED externo con resistencia y salida PWM apta, más alimentación acorde; no conectes LED de potencia directo.","program":["Usa «escribir pin analógico» en P0 y sube intensidad de 0 a 1023 en pasos","espera entre pasos","baja de nuevo hasta 0."],"test":"En 10 s se observan al menos dos ciclos suaves de subida y bajada.","levels":[{"task":"Enciende y apaga con cinco niveles","success":"Se reconocen cinco pasos"},{"task":"Consigue transición de 10 pasos sin salto brusco","success":"El brillo aumenta y disminuye"},{"task":"Permite ajustar velocidad con botones","success":"Dos ritmos distintos se observan claramente"}],"warning":"La escritura PWM no controla correctamente un LED de potencia sin etapa adecuada."},"04-06":{"prep":"Módulo RGB TA647 con alimentación y pines compatibles; identifica si es RGB analógico o direccionable antes de programar.","program":["Consulta tipo de módulo","en RGB analógico define canales R/G/B con salidas PWM y controladores adecuados","en RGB direccionable instala su extensión específica","prueba rojo, verde y azul por separado."],"test":"Comprueba tres colores primarios y un color mezclado sin sobrepasar tensión.","levels":[{"task":"Muestra rojo, verde y azul por separado","success":"Se ven los tres colores correctos"},{"task":"Mezcla dos canales para amarillo y cian","success":"Los colores coinciden con la tabla RGB"},{"task":"Crea transición gradual entre tres colores","success":"Tres mezclas suaves sin parpadeos"}],"warning":"Los pines y el código varían según el RGB del kit: no todos admiten tres salidas PWM directas."},"04-07":{"prep":"Solo micro:bit; prepara secuencia de colores o iconos y una tabla de equivalencias para botones.","program":["Guarda lista de instrucciones","muestra una secuencia de uno o dos iconos","recibe respuestas con A/B","compara cada respuesta con el elemento correspondiente y muestra acierto o error."],"test":"Prueba una secuencia correcta y otra incorrecta de dos elementos.","levels":[{"task":"Repite una secuencia de dos señales","success":"Correcta da ✓ y errónea X"},{"task":"Aumenta dificultad hasta cuatro señales","success":"Tres partidas muestran la secuencia correcta"},{"task":"Genera secuencias aleatorias y guarda récord","success":"El récord coincide con el mejor resultado"}],"warning":"Mostrar una secuencia y leer botones exige gestionar índices; no compares solo la última pulsación."},"04-08":{"prep":"Micro:bit V2 y salida luminosa; el sonido debe ser audible sin ser estridente. Vibrador solo con controlador externo.","program":["Crea evento A para alerta","activa icono y sonido breve","añade una segunda señal visual intermitente","el botón B debe detener todas las salidas."],"test":"Dos compañeros deben entender el aviso sin mirar el sonido o sin mirar la luz, respectivamente.","levels":[{"task":"Aviso con luz y sonido","success":"Se recibe por dos canales independientes"},{"task":"Añade botón B para silenciar","success":"B detiene sonido pero mantiene señal visual"},{"task":"Incluye vibración mediante controlador seguro","success":"Se activa sin alimentar motor desde micro:bit"}],"warning":"Un motor de vibración requiere transistor o controlador y fuente apropiada."},"04-09":{"prep":"Micro:bit, cartón y LED opcionales; define qué acción del público activará el efecto.","program":["Elige una entrada (botón, luz o movimiento)","lee su estado","establece dos respuestas diferentes con iconos/sonidos","ensaya la interacción con tres visitantes."],"test":"Cada visitante debe activar el efecto sin instrucciones adicionales.","levels":[{"task":"Reacciona a un gesto de forma reproducible","success":"Tres personas provocan la misma respuesta"},{"task":"Añade segunda respuesta dependiente de intensidad","success":"Se diferencian claramente dos estímulos"},{"task":"Diseña experiencia de 45 s con inicio y final","success":"Tres visitantes explican qué han hecho y observado"}],"warning":"Evita sonidos intensos o LED deslumbrantes; pide permiso antes de grabar visitantes."},"05-01":{"prep":"Maqueen Plus V2 con micro:bit en el zócalo y batería correcta. Marca 20 cm de pista libre.","program":["En MakeCode instala «Maqueen Plus V2» desde Extensiones","al iniciar configura el robot","al pulsar A ordena ambos motores adelante a velocidad baja, espera y detén."],"test":"Eleva ruedas antes de descargar; después recorre 20 cm aproximadamente y se detiene.","levels":[{"task":"Avanza y se detiene sin intervención","success":"Dos ensayos de 20 cm con error de ±5 cm"},{"task":"Compara tiempos a dos velocidades","success":"Tabla de cuatro ensayos reproducibles"},{"task":"Calibra 50 cm con tres pruebas","success":"Dos de tres a ±5 cm de la meta"}],"warning":"La distancia depende de carga, batería y suelo; no confundas velocidad con centímetros."},"05-02":{"prep":"Maqueen Plus V2 y cartulina con círculo de 40 cm. Sin cables Dupont para motores integrados.","program":["Activa motor izquierdo más lento que derecho","espera un tiempo corto","detén ambos","invierte las velocidades para girar al otro lado."],"test":"Hace dos curvas opuestas dentro del circuito marcado.","levels":[{"task":"Gira a ambos lados sin chocar","success":"Dos maniobras de cada lado controladas"},{"task":"Calibra giro aproximado de 90°","success":"Error menor de 15° dos veces"},{"task":"Traza ocho usando dos giros conectados","success":"Completa figura sin tocar bordes"}],"warning":"Los giros por tiempo no son exactos: mide y ajusta un parámetro cada vez."},"05-03":{"prep":"Maqueen Plus V2; localiza faros y conmutador del zumbador antes de empezar.","program":["En «al iniciar» apaga luces","con A enciende faros y reproduce aviso corto","mueve ambos motores lentamente durante un segundo","detén y apaga las luces."],"test":"El sonido y las luces preceden al movimiento; finaliza inmóvil.","levels":[{"task":"Realiza una secuencia luz→tono→avance→parada","success":"Tres ejecuciones completas"},{"task":"Alterna luces izquierda/derecha antes de un giro","success":"La señal corresponde al giro"},{"task":"Crea patrulla de tres tramos con señal de emergencia","success":"Completa la ruta y se para al pulsar A+B"}],"warning":"Usa la categoría real de luces de la extensión V2, no los bloques de la matriz 5×5."},"05-04":{"prep":"Maqueen Plus V2 con ultrasónico conectado al conector del propio robot y obstáculos blandos.","program":["Inicializa Maqueen","dentro de «para siempre» lee distancia TRIG P13/ECHO P14","si medida válida menor de 20 cm detén motores","de lo contrario avanza despacio."],"test":"Acerca cartón a 40, 25 y 15 cm; el robot nunca debe tocarlo.","levels":[{"task":"Se detiene antes de 20 cm","success":"Tres aproximaciones sin contacto"},{"task":"Activa aviso entre 20 y 35 cm","success":"Aviso previo y parada final ocurren en orden"},{"task":"Compara dos velocidades y distancias de frenado","success":"Tabla de seis medidas sin colisiones"}],"warning":"Si el sensor devuelve 0 o valor inválido, trata la medida como fallo seguro, no como permiso de avanzar."},"05-05":{"prep":"Maqueen Plus V2, pista blanca con cinta negra mate; sensores de línea integrados, sin Shield adicional.","program":["Comprueba lecturas negro/blanco con robot parado","identifica sensor central y laterales","en el bucle, centra si M detecta línea, corrige según L1/R1 y detén si se pierde."],"test":"Completa una línea de un metro con dos curvas amplias.","levels":[{"task":"Sigue recta durante un metro","success":"No abandona la cinta"},{"task":"Supera dos curvas suaves sin ayuda","success":"Completa dos de tres intentos"},{"task":"Añade búsqueda breve de línea al perderla","success":"Recupera sin salirse de la zona delimitada"}],"warning":"La detección de negro puede codificarse 0 o 1 según calibración: compruébalo antes."},"05-06":{"prep":"Maqueen Plus V2, cinta negra con curvas pronunciadas y una zona de línea perdida.","program":["Usa L2/L1/M/R1/R2 para detectar posición de línea","asigna tres velocidades de corrección y memoria de último lado","si no hay señal reduce velocidad y busca de forma limitada."],"test":"Registra tres vueltas con número de salidas de pista y tiempo.","levels":[{"task":"Supera una curva de 90°","success":"Dos de tres intentos sin salirse"},{"task":"Recupera línea tras interrupción de 4 cm","success":"La encuentra sin ayuda manual"},{"task":"Optimiza tiempo sin aumentar salidas","success":"La última versión mejora tiempo y mantiene ≤1 salida"}],"warning":"No aumentes velocidad antes de demostrar recuperación segura."},"05-07":{"prep":"Maqueen Plus V2 y linterna de baja intensidad; micro:bit orientada con su pantalla hacia arriba.","program":["Lee luz con micro:bit","aproxima la linterna y fija umbral","cuando hay iluminación alta avanza lentamente y cuando no, detén","añade una pausa de lectura."],"test":"El robot arranca al iluminar y se para al cubrir la luz sin tocar sensores.","levels":[{"task":"Responde a luz/sombra de forma fiable","success":"Cinco cambios correctos"},{"task":"Crea dos velocidades con dos umbrales","success":"Se distinguen dos velocidades"},{"task":"Haz un recorrido de luz por tres estaciones","success":"Llega a cada estación y para sin choque"}],"warning":"Sin dos fotodetectores separados no puede localizar dirección de la luz; esto es reacción, no búsqueda direccional."},"05-08":{"prep":"Dos micro:bit; solo el receptor va montado en Maqueen Plus V2. Asigna grupo radio distinto del resto del aula.","program":["En ambos inicia el mismo grupo","emisor A envía «F» y B «S»","receptor, al recibir, manda avanzar o detener","agrega botón A+B y temporizador de pérdida de señal."],"test":"A 1 m, cinco órdenes consecutivas deben producir el efecto previsto.","levels":[{"task":"Avanza y se detiene desde otro equipo","success":"Cinco órdenes correctas"},{"task":"Añade giros izquierda y derecha","success":"Circuito con dos curvas sin tocar paredes"},{"task":"Parada por ausencia de señal tras 2 s","success":"Apaga emisor y robot se para en ≤2 s"}],"warning":"Emisor no necesita extensión Maqueen; receptor sí. No olvides la parada automática."},"05-09":{"prep":"Maqueen Plus V2, laberinto de cartón con paredes blandas y salida marcada.","program":["Dibuja estrategia simple de exploración","mide frente al robot y ejecuta giros cortos cuando hay obstáculo","comprueba después del giro antes de avanzar."],"test":"Completa un recorrido con un giro y un obstáculo sin tocar paredes.","levels":[{"task":"Esquiva un obstáculo y recupera marcha","success":"Tres pruebas sin choque"},{"task":"Resuelve laberinto de tres cruces","success":"Sale sin tocar bordes"},{"task":"Compara estrategia derecha/izquierda","success":"Tabla de tiempos y colisiones justifica una elección"}],"warning":"Un solo ultrasonidos frontal no ve paredes laterales; evita prometer navegación perfecta."},"06-01":{"prep":"Micro:bit, Shield del TA647 y un LED módulo. Trabaja con alimentación desconectada.","program":["Introduce micro:bit en zócalo de la Shield sin cables entre placas","localiza G (masa), V (alimentación) y S (señal)","conecta módulo a puerto compatible respetando etiquetas."],"test":"El profesor comprueba tensión, orientación y pin antes de encender.","levels":[{"task":"Identifica S/V/G en dos conectores","success":"Señala cada uno sin confusión"},{"task":"Conecta un LED módulo y lo controla con un pin","success":"Tres encendidos y apagados"},{"task":"Dibuja esquema y verifica continuidad","success":"Una pareja monta sin ayuda y sin invertir V/G"}],"warning":"No asumas que todas las Shields tienen idéntico orden S/V/G ni que 5 V es seguro para entradas."},"06-02":{"prep":"Shield con micro:bit, pulsador, LED con resistencia o módulo LED y Dupont adecuados.","program":["Conecta pulsador a entrada P0 y módulo LED a salida P1 con masa común","define si el pulsador es activo ALTO o BAJO","lee P0 y escribe P1 según estado."],"test":"Pulsa cinco veces: el LED cambia correctamente sin parpadeos falsos.","levels":[{"task":"Pulsa para encender, suelta para apagar","success":"Cinco repeticiones correctas"},{"task":"Convierte el pulsador en conmutador","success":"Cinco pulsaciones alternan estado"},{"task":"Añade antirrebote y cuenta pulsaciones","success":"Una pulsación se cuenta una sola vez"}],"warning":"No conectes un LED desnudo sin resistencia ni un pulsador sin polarización definida."},"06-03":{"prep":"Servo 180°, micro:bit en Shield y fuente apropiada; comprueba masa común.","program":["Señal del servo a salida compatible P0","positivo a alimentación apta para servo y negativo a GND","usa «escribir servo» a 0°, 90° y 180° con pausas."],"test":"Con hélice descargada, el brazo alcanza tres posiciones sin vibraciones excesivas.","levels":[{"task":"Mueve servo a 0° y 90°","success":"Dos posiciones reproducibles"},{"task":"Añade 180° con botón B","success":"Tres posiciones sin atascar"},{"task":"Haz saludo suave por pasos de 15°","success":"Movimiento sin saltos bruscos"}],"warning":"Nunca alimentes el servo directamente de un pin de micro:bit."},"06-04":{"prep":"Servo 180°, pulsador del kit, Shield, cartón y fuente correcta; despeja la barrera.","program":["Construye barrera ligera","usa pulsador en P0 y servo señal P1","inicia a 0° (cerrado)","al pulsar abre 90°, espera dos segundos y cierra."],"test":"Cinco pulsaciones abren y cierran sin golpear el soporte.","levels":[{"task":"Abre con botón y vuelve a cerrar","success":"Cinco ciclos sin atasco"},{"task":"Añade aviso luminoso durante movimiento","success":"La luz cambia antes de levantar barrera"},{"task":"Cuenta vehículos y bloquea al llegar a tres","success":"La barrera no abre desde el cuarto vehículo"}],"warning":"Verifica que el servo pueda girar físicamente sin forzarlo contra el cartón."},"06-05":{"prep":"Servo continuo 360°, fuente compatible y Shield. No coloques brazos largos hasta calibrar.","program":["Envía señal neutral alrededor de 90","mide si se detiene","usa valores a ambos lados para girar en sentidos opuestos","vuelve siempre al neutral tras cada ensayo."],"test":"Registra dirección y velocidad aproximada en tres señales distintas.","levels":[{"task":"Detén y gira en ambos sentidos","success":"Tres estados distinguibles"},{"task":"Regula dos velocidades de giro","success":"Las diferencias se perciben sin carga"},{"task":"Controla sentido y tiempo mediante botones","success":"Los dos botones responden y hay parada segura"}],"warning":"En servo continuo 0°/180° NO son ángulos de posición; aproximadamente 90 es neutral."},"06-06":{"prep":"Motor DC, L298N, fuente de motor separada, micro:bit en Shield, Dupont y masa común.","program":["Conecta motor a OUT del controlador y alimentación a bornes del controlador","entradas IN1/IN2 a pines digitales y ENA a PWM","usa combinaciones adelante, atrás, parada."],"test":"Con ruedas elevadas prueba 3 s en cada sentido sin invertir cables en caliente.","levels":[{"task":"Avanza, para y retrocede","success":"Tres órdenes sin sobrecalentamiento"},{"task":"Controla dos velocidades mediante PWM","success":"Se distinguen dos velocidades"},{"task":"Añade parada de emergencia y protección de cambio de sentido","success":"Siempre para antes de invertir"}],"warning":"No conectes motor a micro:bit ni compartas alimentación sin comprobar voltajes y corriente."},"06-07":{"prep":"OLED 1,3'' o LCD1602 I²C del kit, micro:bit en Shield; identifica dirección, 3,3/5 V y extensión compatible.","program":["Inserta placa apagada","conecta SDA/SCL a las señales I²C del shield y GND común","instala extensión de pantalla correcta","primero escribe «Hola» en pantalla EXTERNA, luego muestra un dato."],"test":"La palabra «Hola» aparece en la pantalla externa, no solo en la matriz de micro:bit.","levels":[{"task":"Escribe texto en la pantalla externa","success":"El texto se ve en el módulo"},{"task":"Muestra temperatura junto a unidad °C","success":"Lectura y unidad visibles en pantalla"},{"task":"Alterna temperatura y otra magnitud real cada 3 s","success":"Dos datos reales y origen identificados"}],"warning":"«mostrar cadena» de Básico escribe en la micro:bit, no en OLED/LCD."},"06-08":{"prep":"Relé TA647, minibomba de agua y fuente de 3–5 V apta; Shield solo manda señal, con montaje supervisado.","program":["Conecta señal del relé a P1 con alimentación compatible","cablea bomba y fuente mediante contactos del relé, nunca a pin micro:bit","controla pulso de 1 s tras pulsar A."],"test":"En recipiente estanco, la bomba se activa 1 s y queda desconectada el resto del tiempo.","levels":[{"task":"Acciona bomba un segundo y se detiene","success":"Tres pulsos sin fuga ni calentamiento"},{"task":"Añade bloqueo entre pulsos de 5 s","success":"No permite activaciones seguidas"},{"task":"Añade nivel bajo de agua o emergencia y corte seguro","success":"Corta alimentación en cada ensayo de fallo"}],"warning":"No uses tensión de red; el relé puede ser activo BAJO y requiere verificar su circuito."},"06-09":{"prep":"Sensor de humedad, relé, bomba y fuente separada, Shield, tierra y recipiente impermeable.","program":["Conecta humedad analógica a P0","calibra seco/húmedo","relé en P1","si suelo está bajo umbral, activa bomba solo pulso corto y espera antes de revaluar."],"test":"Realiza tres ciclos con tierra seca y tres con húmeda; nunca mantiene bomba encendida continuamente.","levels":[{"task":"Da aviso de sequedad sin activar bomba","success":"Acierta cuatro de cinco mediciones"},{"task":"Riega un pulso solo en seco","success":"Tres ciclos y corte posterior"},{"task":"Añade límite de riegos y alarma de depósito vacío","success":"No hay riego cuando el límite se supera"}],"warning":"La bomba necesita alimentación y control adecuados, no se alimenta desde S de Shield."},"07-01":{"prep":"Dos micro:bit; colocad los equipos a 1–2 m y asignad un grupo de radio para no interferir con otros.","program":["Ambas placas configuran grupo 15","emisor al pulsar A envía «HOLA»","receptor usa «al recibir cadena» para mostrar palabra y confirmación."],"test":"En cinco envíos, el receptor muestra cinco mensajes sin pulsar sus botones.","levels":[{"task":"Envía texto de una placa a otra","success":"Cinco mensajes recibidos"},{"task":"Añade respuesta «RECIBIDO» desde la segunda","success":"Se completa diálogo de ida y vuelta"},{"task":"Mide alcance dentro del aula sin perder mensajes","success":"Tabla de distancias y aciertos con mínimo tres posiciones"}],"warning":"Para comunicar, ambos proyectos deben usar el mismo grupo de radio."},"07-02":{"prep":"Dos micro:bit y tabla de códigos de tres números; elegid tres significados sencillos.","program":["Define «1=ayuda, 2=listo, 3=alto»","emisor manda número elegido por botón","receptor usa «si» para traducirlo a icono o texto."],"test":"Verifica los tres códigos correctos y un valor desconocido.","levels":[{"task":"Envía dos mensajes numéricos distintos","success":"El receptor los distingue"},{"task":"Añade tercer código y aviso para desconocidos","success":"Cuatro casos responden correctamente"},{"task":"Crea protocolo con confirmación de recepción","success":"Cinco mensajes tienen confirmación o aviso de fallo"}],"warning":"Documenta la correspondencia: emisor y receptor deben interpretar los mismos números."},"07-03":{"prep":"Tres micro:bit si hay disponibles; si son dos, realiza una encuesta por turnos. Asigna una pregunta con opciones A/B.","program":["En cada votante A envía 1 y B envía 2 una sola vez","el receptor acumula contadores separados y al pulsar B muestra resultados."],"test":"Reúne seis votos, registra los resultados y comprueba que A+B suman 6.","levels":[{"task":"Recoge respuestas A/B de dos placas","success":"Se contabilizan sin duplicados"},{"task":"Impide doble voto por ronda","success":"Un votante no suma dos respuestas"},{"task":"Realiza dos preguntas consecutivas con reinicio","success":"Cada ronda contabiliza solo sus votos"}],"warning":"Una respuesta reenviada puede contarse dos veces: identifica remitente o bloquea votos por ronda."},"07-04":{"prep":"Maqueen Plus V2 y micro:bit emisora; pista libre y grupo 20. Ruedas levantadas en la primera prueba.","program":["Emisor manda F/S/L/R","receptor controla motores según mensaje","guarda instante del último mensaje recibido","dentro de «para siempre», si pasan más de 2 s detiene todos los motores."],"test":"Apaga el emisor a mitad de avance: el robot debe detenerse en dos segundos como máximo.","levels":[{"task":"Mueve robot con F y S","success":"Cinco órdenes correctas"},{"task":"Añade L y R con parada intermedia","success":"Completa ruta de dos giros"},{"task":"Parada automática de emergencia por pérdida de señal","success":"Tres pérdidas de radio terminan en stop"}],"warning":"Sin temporizador de desconexión el robot podría seguir moviéndose indefinidamente."},"07-05":{"prep":"Tres micro:bit si hay disponibles; nómbralas A, B y central y asigna grupo común.","program":["Cada estación envía «temperatura» con identificador único y unidad","central usa «al recibir nombre/valor» y guarda el último dato de cada estación."],"test":"Recibe al menos tres lecturas por estación y anota su origen.","levels":[{"task":"Dos nodos envían lectura identificada","success":"La central distingue A y B"},{"task":"Añade tercer nodo sin sobrescribir valores previos","success":"Se conservan tres medidas separadas"},{"task":"Detecta una estación desconectada tras 10 s","success":"Se muestra alerta solo del nodo ausente"}],"warning":"Un dato sin identificador puede confundirse con el de otra estación."},"07-06":{"prep":"Dos micro:bit; define un paquete sencillo: dato 0–9 y dígito de control.","program":["En emisor calcula checksum = (dato+3) módulo 10","envía dato y checksum","en receptor recalcula y acepta solo coincidencias","prueba mensajes alterados intencionalmente."],"test":"Simula tres mensajes correctos y tres incorrectos; el receptor distingue ambos casos.","levels":[{"task":"Valida una pareja dato/checksum","success":"Tres parejas válidas pasan"},{"task":"Descarta tres parejas manipuladas","success":"Los tres fallos se detectan"},{"task":"Añade contador de paquetes aceptados/rechazados","success":"Se comprueba con seis ensayos"}],"warning":"Checksum simple detecta algunos errores, no protege de manipulación intencionada ni todos los fallos."},"07-07":{"prep":"Dos Maqueen Plus V2, dos micro:bit emisoras o una central, línea de salida y recorrido corto.","program":["La central envía «PREPARADOS» y luego «SALIDA»","cada robot debe estar detenido hasta recibir «SALIDA»","ejecuta avance de duración calibrada y para."],"test":"Ninguno mueve ruedas antes de la orden y ambos se detienen al acabar.","levels":[{"task":"Salida simultánea de dos robots","success":"Ninguno arranca antes del mensaje"},{"task":"Cronometra diferencias en cinco carreras","success":"Tabla con cinco tiempos por robot"},{"task":"Añade alarma de cancelación «STOP» prioritaria","success":"Ambos se detienen ante STOP en tres pruebas"}],"warning":"No presupongas sincronía perfecta de radio; mide la diferencia real."},"07-08":{"prep":"Dos micro:bit o sensores de puerta del TA647; arma una maqueta de cartón.","program":["Cada nodo detecta puerta/movimiento","envía «Z1» o «Z2» con identificador","central muestra zona y activa aviso","botón B reinicia después de revisión."],"test":"Activa alternativamente cada zona: la central siempre indica la fuente correcta.","levels":[{"task":"Alerta al abrir una puerta","success":"Cinco detecciones correctas"},{"task":"Distingue dos zonas en una central","success":"Muestra Z1 y Z2 sin confundirlas"},{"task":"Añade silencio temporal y registro de activaciones","success":"Se almacenan cinco sucesos y puede reiniciarse"}],"warning":"Es solo una maqueta educativa; no utilizar como alarma de seguridad real."},"07-09":{"prep":"Tres micro:bit o equipos compartidos por turnos y una central; dibuja mapa de red simple.","program":["Cada nodo envía ID y medida en intervalos","la central valida ID y guarda último valor","usa botón A para recorrer datos y B para mostrar alertas."],"test":"Una tabla presenta últimos valores de al menos tres nodos.","levels":[{"task":"Recibe dos nodos con identificación","success":"Las medidas no se mezclan"},{"task":"Añade tercer nodo y consulta con A","success":"A recorre tres valores distintos"},{"task":"Detecta datos antiguos y repite transmisión fallida","success":"Se reconoce la desconexión en tres ensayos"}],"warning":"La radio no garantiza entrega ni orden: planifica reintentos y marcas de tiempo."},"08-01":{"prep":"Solo micro:bit y listado de tres tareas de clase; asigna duración breve, por ejemplo 30 s.","program":["Con A inicia temporizador","muestra cuenta atrás en la matriz","con B pausa o reinicia según reglas escritas","al finalizar muestra icono y tono opcional."],"test":"Ensaya dos ciclos consecutivos sin valores negativos.","levels":[{"task":"Temporiza 30 s y finaliza","success":"La señal aparece entre 29 y 32 s"},{"task":"Añade pausa y reanudación sin perder segundos","success":"Tres pausas conservan tiempo restante"},{"task":"Crea menú de 30/60/90 s y registro de tareas","success":"Tres duraciones medidas y etiquetadas"}],"warning":"No uses un bucle bloqueante que impida responder al botón de pausa."},"08-02":{"prep":"Solo micro:bit; prepara seis preguntas numeradas y su solución en papel.","program":["Al agitar genera número al azar de 1–6","muestra número","compañero lee pregunta correspondiente","con B confirma respuesta y registra puntos."],"test":"En diez tiradas aparecen solo preguntas 1–6 y se contabilizan aciertos.","levels":[{"task":"Selecciona una pregunta al azar","success":"Diez números entre 1 y 6"},{"task":"Añade puntuación por respuestas correctas","success":"Marcador coincide con cinco respuestas"},{"task":"Evita repetir la misma pregunta consecutiva","success":"Diez rondas sin dos iguales seguidas"}],"warning":"La micro:bit selecciona, pero no valida respuestas orales sin entrada adicional."},"08-03":{"prep":"Estructura para proteger huevo, micro:bit protegida y sujeta a una maqueta de prueba sin objetos frágiles.","program":["Registra aceleración máxima al mover el prototipo por un recorrido seguro","muestra el máximo con A y reinicia con B","compara dos diseños con misma prueba."],"test":"Haz tres ensayos por diseño y registra máximos con misma altura y superficie.","levels":[{"task":"Mide impacto en un modelo de prueba","success":"Tres medidas registradas"},{"task":"Compara dos amortiguaciones","success":"Tabla de seis lecturas con mismo método"},{"task":"Diseña mejora y repite ensayo","success":"La mediana de aceleración disminuye respecto a la versión inicial"}],"warning":"No lances micro:bit sin protección; el dato del acelerómetro no equivale a fuerza directamente."},"08-04":{"prep":"Cartón, sensor de humedad TA647, micro:bit y Shield; motor/bomba solo si dispone de controlador y fuente segura.","program":["Construye maqueta de maceta","calibra sensor seco/húmedo","mide luz con micro:bit","presenta dos avisos independientes","no actives bomba en la primera fase."],"test":"En cuatro situaciones (seco/húmedo × luz/sombra) salen avisos coherentes.","levels":[{"task":"Muestra aviso por sequedad","success":"Acierta cuatro de cinco ensayos"},{"task":"Añade aviso por luz insuficiente","success":"Las cuatro combinaciones producen resultado correcto"},{"task":"Integra riego por pulsos con relé y fuente supervisada","success":"Tres ciclos sin bomba encendida permanentemente"}],"warning":"No alimentes bomba desde un pin ni presupongas que humedad es mayor cuando hay agua."},"08-05":{"prep":"Micro:bit y caja de cartón; crea tres pruebas de lógica y una clave final de tres dígitos.","program":["Programa fase 1,2,3","cada solución correcta avanza fase y muestra pista","los errores no desbloquean","al completar tres pruebas aparece el código de salida."],"test":"Un equipo ajeno completa la secuencia sin instrucciones orales.","levels":[{"task":"Resuelve una prueba y muestra pista","success":"La pista no aparece antes del acierto"},{"task":"Añade las tres pruebas encadenadas","success":"Los fallos no permiten saltarse fases"},{"task":"Crea temporizador y pistas opcionales","success":"Dos grupos completan o reciben pista al agotarse tiempo"}],"warning":"No guardes el progreso en una variable que se reinicie entre cada pulsación."},"08-06":{"prep":"Maqueta de cartón, micro:bit, dos LED con resistencias y sensor compatible del TA647.","program":["Dibuja plano con cruce, farola y paso peatonal","programa por separado el semáforo y la farola automática","integra estado de seguridad que apague salidas ante fallo."],"test":"Enseña tres escenarios: luz diurna, noche y petición peatonal; nadie recibe verde contradictorio.","levels":[{"task":"Automatiza una farola con luz","success":"Cinco pruebas luz/sombra correctas"},{"task":"Integra semáforo con botón peatonal","success":"Tres ciclos sin rojos y verdes incompatibles"},{"task":"Añade registro de consumo y modo ahorro","success":"Tabla compara dos estrategias con medición o estimación declarada"}],"warning":"La maqueta no representa control de tráfico real; salidas y alimentación deben ser seguras."},"08-07":{"prep":"Maqueen Plus V2, pista de un metro y cronómetro; batería similar entre comparaciones.","program":["Programa tres modos: avance rápido, avance lento y avance con paradas","registra tiempo y consumo estimado solo si dispones de instrumento","compara misma distancia."],"test":"Tres ensayos por estrategia con condiciones iguales y tabla de resultados.","levels":[{"task":"Recorre un metro a velocidad moderada","success":"Tres tiempos registrados"},{"task":"Compara lento y rápido con mismas condiciones","success":"Explica diferencias observadas"},{"task":"Optimiza ruta y documenta energía medida o estimada","success":"No llama «consumo real» a una estimación no medida"}],"warning":"Sin medidor de corriente no puedes afirmar cuánto ha consumido la batería."},"08-08":{"prep":"Maqueen Plus V2, carga blanda muy ligera, cinta y tres zonas señaladas en suelo.","program":["Diseña bandeja estable y ruta A→B","prueba motores sin carga","programa avance, giro y parada","añade comprobación de obstáculo a distancia segura."],"test":"Entrega carga en dos de tres recorridos sin caída ni colisión.","levels":[{"task":"Transporta carga ligera 50 cm","success":"Dos de tres recorridos sin caída"},{"task":"Entrega en zona B tras un giro","success":"Acaba en zona de 30×30 cm"},{"task":"Planifica dos destinos y evita obstáculo","success":"Completa tres tramos y registra correcciones"}],"warning":"No coloques cargas pesadas o elevadas que comprometan la estabilidad del robot."},"08-09":{"prep":"Prototipo propio del kit, cartel de problema/solución y registro de pruebas; equipos con roles.","program":["Define necesidad real","dibuja esquema","construye versión mínima","programa interacción","recoge tres resultados medibles","prepara exposición de tres minutos."],"test":"Un visitante entiende qué resuelve y puede realizar una prueba supervisada sin intervención del autor.","levels":[{"task":"Presenta prototipo funcional y su propósito","success":"Demostración de 60 s sin ayuda"},{"task":"Explica un fallo real y su corrección","success":"Incluye foto antes/después y prueba repetida"},{"task":"Defiende mejora con datos y responde preguntas","success":"Tres pruebas y dos decisiones justificadas"}],"warning":"No presentes una simulación como si fuera medida real del hardware."}};

// Preguntas contextualizadas: sustituyen test antiguos que mezclaban conceptos de otras misiones.
for(const m of (window.BITABIT_DATA?.missions||[])){
 const g=window.ROBO_MISION_GUIAS_V28[m.id];
 if(!g)continue;
 m.question='¿Qué prueba permite demostrar que has completado «'+m.title+'»?';
 m.options=[g.test,'Solo abrir MakeCode sin ejecutar ninguna prueba.','Cambiar el programa sin observar su resultado.'];
 m.correct=0;
 m.question2='¿Qué precaución es importante específicamente en esta misión?';
 m.options2=['Elegir el color de la carcasa antes de programar.','Cambiar el nombre del archivo en cada ensayo.',g.warning];
 m.correct2=2;
}
